using System;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;
public static class DressDetailedClasses{
 static GameObject go;static Animator rig;static string dir;
 static Mesh Save(Mesh mesh,string name){mesh.name=name;string path=dir+"/"+name+".asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(old){old.Clear();old.vertices=mesh.vertices;old.normals=mesh.normals;old.uv=mesh.uv;old.triangles=mesh.triangles;old.boneWeights=mesh.boneWeights;old.bindposes=mesh.bindposes;old.RecalculateBounds();old.RecalculateTangents();old.UploadMeshData(false);EditorUtility.SetDirty(old);UnityEngine.Object.DestroyImmediate(mesh);return old;}AssetDatabase.CreateAsset(mesh,path);return mesh;}
 static Material Fabric(string name,Color color){string path=dir+"/"+name+".mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(path);if(!mat){mat=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(mat,path);}mat.SetColor("_BaseColor",color);mat.SetFloat("_Smoothness",.12f);mat.SetFloat("_Cull",0);mat.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/03_Models/Characters/CindersDetailed/Priest/robe text.png"));EditorUtility.SetDirty(mat);return mat;}
 static void Cloth(string name,Vector3[] vs,Vector2[] uv,int[] tris,Material mat,Transform parent){var mesh=new Mesh{vertices=vs,uv=uv,triangles=tris};mesh.RecalculateNormals();mesh.RecalculateBounds();mesh.RecalculateTangents();var obj=new GameObject(name);obj.transform.SetParent(go.transform,false);obj.AddComponent<MeshFilter>().sharedMesh=Save(mesh,name);obj.AddComponent<MeshRenderer>().sharedMaterial=mat;obj.transform.SetParent(parent,true);}
 static void Hood(Material cloth){var head=rig.GetBoneTransform(HumanBodyBones.Head);var vs=new List<Vector3>();var uv=new List<Vector2>();var tris=new List<int>();int rows=20,cols=48;for(int j=0;j<=rows;j++){float t=j/(float)rows;float y=-.08f+t*.34f;float width=t<.58f?Mathf.Lerp(.145f,.137f,t/.58f):.137f*Mathf.Sqrt(Mathf.Max(.001f,1-Mathf.Pow((t-.58f)/.42f,2)));float depth=width*1.08f;for(int i=0;i<=cols;i++){float u=i/(float)cols;float angle=Mathf.Lerp(.74f,Mathf.PI*2-.74f,u);float fold=1+.035f*Mathf.Cos(angle*9+t*8);var p=head.position+new Vector3(Mathf.Sin(angle)*width*fold,y,Mathf.Cos(angle)*depth*fold-.01f);vs.Add(p);uv.Add(new Vector2(.1f+u*.35f,.3f+t*.35f));if(i>0&&j>0){int k=j*(cols+1)+i;tris.AddRange(new[]{k,k-1,k-cols-2,k,k-cols-2,k-cols-1});}}}Cloth("Capucha de peregrino",vs.ToArray(),uv.ToArray(),tris.ToArray(),cloth,head);
 // Wrapped lower face, leaving only a recessed dark eye slit.
 vs.Clear();uv.Clear();tris.Clear();for(int j=0;j<=10;j++)for(int i=0;i<=32;i++){float t=j/10f,u=i/32f,angle=(u-.5f)*2.9f;vs.Add(head.position+new Vector3(Mathf.Sin(angle)*(.108f+.012f*t),-.065f+t*.15f+Mathf.Sin(u*8)*.005f,Mathf.Cos(angle)*(.118f+.012f*t)));uv.Add(new Vector2(.15f+u*.25f,.25f+t*.2f));if(i>0&&j>0){int k=j*33+i;tris.AddRange(new[]{k,k-1,k-34,k,k-34,k-33});}}Cloth("Velo cerrado",vs.ToArray(),uv.ToArray(),tris.ToArray(),cloth,head);
 }
 static void Cape(Material mat,float length,float width,string name){var chest=rig.GetBoneTransform(HumanBodyBones.Chest);var vs=new List<Vector3>();var uv=new List<Vector2>();var tri=new List<int>();for(int j=0;j<=24;j++)for(int i=0;i<=24;i++){float t=j/24f,u=i/24f;float x=(u-.5f)*width*(.7f+t*.3f);float y=1.49f-length*t+(j==24?.018f*Mathf.Sin(i*2.4f):0);float z=-.10f-.10f*Mathf.Sin(t*Mathf.PI*.7f)+.028f*Mathf.Cos(u*Mathf.PI*10)*(t+.2f);vs.Add(new Vector3(x,y,z));uv.Add(new Vector2(.05f+u*.5f,.2f+t*.6f));if(i>0&&j>0){int k=j*25+i;tri.AddRange(new[]{k,k-1,k-26,k,k-26,k-25});}}Cloth(name,vs.ToArray(),uv.ToArray(),tri.ToArray(),mat,chest);}
 static void Collar(Material mat){var vs=new List<Vector3>();var uv=new List<Vector2>();var tris=new List<int>();for(int j=0;j<=10;j++)for(int i=0;i<=48;i++){float t=j/10f,u=i/48f,angle=u*Mathf.PI*2;float r=Mathf.Lerp(.145f,.095f,t)+.007f*Mathf.Sin(t*25+angle*2);vs.Add(new Vector3(Mathf.Sin(angle)*r,1.48f+t*.14f,Mathf.Cos(angle)*r+.015f));uv.Add(new Vector2(.15f+u*.3f,.3f+t*.3f));if(i>0&&j>0){int k=j*49+i;tris.AddRange(new[]{k,k-1,k-50,k,k-50,k-49});}}Cloth("Cuello envuelto",vs.ToArray(),uv.ToArray(),tris.ToArray(),mat,rig.GetBoneTransform(HumanBodyBones.Neck));}
 static void RemoveFace(){var r=go.GetComponentsInChildren<SkinnedMeshRenderer>().First(x=>x.name=="body_0");var m=UnityEngine.Object.Instantiate(r.sharedMesh);var v=m.vertices;var old=m.triangles;var kept=new List<int>();for(int i=0;i<old.Length;i+=3)if((v[old[i]].y+v[old[i+1]].y+v[old[i+2]].y)/3<1.555f)kept.AddRange(new[]{old[i],old[i+1],old[i+2]});m.triangles=kept.ToArray();r.sharedMesh=Save(m,"Cuerpo sin rostro");}
 static void Helmet(){var source=Resources.Load<GameObject>("Presentation/Classes/Warrior");var smr=source.GetComponentInChildren<SkinnedMeshRenderer>();var mesh=UnityEngine.Object.Instantiate(smr.sharedMesh);var vs=mesh.vertices;var tris=mesh.triangles;var kept=new List<int>();for(int i=0;i<tris.Length;i+=3)if((vs[tris[i]].y+vs[tris[i+1]].y+vs[tris[i+2]].y)/3>1.51f&&Mathf.Abs(vs[tris[i]].x)<.15f&&Mathf.Abs(vs[tris[i+1]].x)<.15f&&Mathf.Abs(vs[tris[i+2]].x)<.15f)kept.AddRange(new[]{tris[i],tris[i+1],tris[i+2]});mesh.triangles=kept.ToArray();mesh.boneWeights=Array.Empty<BoneWeight>();mesh.bindposes=Array.Empty<Matrix4x4>();var obj=new GameObject("Yelmo de hierro");obj.transform.SetParent(go.transform,false);obj.AddComponent<MeshFilter>().sharedMesh=Save(mesh,"Yelmo de hierro");var m=new Material(smr.sharedMaterial);m.SetColor("_BaseColor",new Color(.46f,.30f,.20f));var path=dir+"/Yelmo.mat";var old=AssetDatabase.LoadAssetAtPath<Material>(path);if(old){EditorUtility.CopySerialized(m,old);UnityEngine.Object.DestroyImmediate(m);m=old;}else AssetDatabase.CreateAsset(m,path);obj.AddComponent<MeshRenderer>().sharedMaterial=m;obj.transform.SetParent(rig.GetBoneTransform(HumanBodyBones.Head),true);}
 public static string Run(){foreach(var role in new[]{"Archer","Shinobi","Berserker","Mage","Warrior","Tank"}){dir="Assets/03_Models/Characters/CindersDetailed/Outfits/"+role;System.IO.Directory.CreateDirectory(dir);AssetDatabase.Refresh();string path="Assets/Resources/Presentation/Classes/"+role+".prefab";go=PrefabUtility.LoadPrefabContents(path);try{rig=go.GetComponentInChildren<Animator>();foreach(var name in new[]{"Capucha de peregrino","Velo cerrado","Capa de viaje","Yelmo de hierro","Cuello envuelto"})foreach(var t in go.GetComponentsInChildren<Transform>().Where(t=>t.name==name).ToArray())UnityEngine.Object.DestroyImmediate(t.gameObject);
 var color=role switch{"Archer"=>new Color(.22f,.30f,.18f),"Shinobi"=>new Color(.15f,.17f,.19f),"Mage"=>new Color(.28f,.22f,.30f),"Tank"=>new Color(.13f,.23f,.23f),_=>new Color(.32f,.10f,.075f)};var cloth=Fabric("Paño envejecido",color);
 if(role=="Archer"||role=="Shinobi"||role=="Berserker"){RemoveFace();var body=go.GetComponentsInChildren<SkinnedMeshRenderer>().First(x=>x.name=="body_0");body.sharedMaterial.SetColor("_BaseColor",role=="Shinobi"?new Color(.28f,.29f,.32f):role=="Archer"?new Color(.48f,.53f,.42f):new Color(.58f,.48f,.39f));EditorUtility.SetDirty(body.sharedMaterial);if(role=="Berserker")Helmet();else Hood(cloth);}
 if(role=="Archer"||role=="Shinobi"||role=="Berserker"||role=="Mage")Collar(cloth);if(role!="Mage")Cape(cloth,role=="Tank"?1.15f:role=="Warrior"?.92f:role=="Archer"?.65f:.43f,role=="Tank"?.60f:.48f,"Capa de viaje");
 if(role=="Mage"){var mantle=go.GetComponentsInChildren<SkinnedMeshRenderer>().FirstOrDefault(x=>x.name=="mantle_0");if(mantle){mantle.sharedMaterial.SetColor("_BaseColor",new Color(.43f,.30f,.38f));EditorUtility.SetDirty(mantle.sharedMaterial);}}
 PrefabUtility.SaveAsPrefabAsset(go,path);}finally{PrefabUtility.UnloadPrefabContents(go);}}AssetDatabase.SaveAssets();return "Closed helmets and hoods applied to all six classes; cloth and silhouettes differentiated";}
}



